import{_ as t,o as a,c as n,a3 as i}from"./chunks/framework.Cliq2K9N.js";const p=JSON.parse('{"title":"Best practices for version management","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/advanced/version-management.md","filePath":"user-guide/advanced/version-management.md","lastUpdated":1787148505000}'),r={name:"user-guide/advanced/version-management.md"};function o(s,e,d,l,m,c){return a(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="best-practices-for-version-management" tabindex="-1">Best practices for version management <a class="header-anchor" href="#best-practices-for-version-management" aria-label="Permalink to &quot;Best practices for version management&quot;">​</a></h1><p>The following is a best practice guide to configuration management / version management of <a href="/user-guide/getting-started.html#important-aireforms-concepts">Forms, Building Blocks and Reference Data</a>.</p><p>In general terms we want the following to be true as our solution and related configuration evolves.</p><ol><li>We want data that has been captured on prior versions to be visible and editable if the context allows.</li><li>We want to be able to query and view prior versions.</li><li>We want new information/data to be captured using the latest published templates.</li><li>We want all persisted data to medico-legally compliant (we know exactly what the healthcare professional was viewing at the time of capture).</li><li>We want to be able to make changes in our development environment with minimal ceremony (breakages are acceptable), and minimal downstream inpact on configuration (such as workflow triggers).</li></ol><p>The tables below represent how change should be managed for forms versions (and related building-block and reference data) that have been used in environments downstream from the development environment, where we need to consider the impact on forms and data, reports etc. Specifically we need to consider the impact on:</p><ol><li>Previously captured and completed forms - can we open read and PDF views.</li><li>Draft forms - which are likely to be subsequently edited and completed.</li><li>Submitted forms which can be amended.</li><li>New forms created with the latest published template / versions.</li></ol><h2 id="reference-data" tabindex="-1">Reference Data <a class="header-anchor" href="#reference-data" aria-label="Permalink to &quot;Reference Data&quot;">​</a></h2><p>Reference data is used when common value-sets sit externally to one or more building blocks. Reference data is a special case in terms of version management as it has a built-in capability to deprecate terms in the value-set meaning that some changes are possible without up-versioning. The table below shows what the recommended course of action is with any given change (🟢 - no need to up-version, ❗ - up-version required, ⚠️ - depends on exact circumstances).</p><table tabindex="0"><thead><tr><th>Change</th><th>Consequences</th><th>Up Version?</th></tr></thead><tbody><tr><td>Remove (deprecate) an existing term</td><td>Existing persisted form data will contain the deprecated term. As the term is deprecated the form will load and the deprecated term will be visible. If the form is submitted it will just be displayed. If the form is draft the term willl appear in the control it will be displayed, however if the value is deselected the end user cannot re-select it. New forms will not show the deprecated term as an option in the control.</td><td>🟢 No</td></tr><tr><td>Minor change in term label</td><td>Existing term is modified (for instance to fix a typo). Draft, New or amended forms will show the new term. Saved forms will be saved with the label the user saw at the time of completing the form (for medico-legal compliance).</td><td>🟢 No</td></tr><tr><td>Semantic changes in term label</td><td>Existing term is amended that changes its meaning in a material way. This will affect interpretation and reporting and is <strong>strongly discouraged</strong>, it is better to deprecate the existing term and add a new term. If you have to do it you will need to up-version.</td><td>❗ Yes</td></tr><tr><td>Adding a new term</td><td>You are adding a new term to an exiting reference data value-set. All the other terms are left unchanged. Technically and data wise this is not a problem for AireFrame, however consideration of whether this is a breaking change is whether the new term is semantically similar or a subset of the existing terms. If it is, it is best to consider it a breaking change from an interpretation and reporting point for view and upversion.</td><td>⚠️ Depends</td></tr><tr><td>Sub-divide a term</td><td>Refine an existing coarse grained term into two or more, fine grained terms. This can be managed by relabling the original term and adding other terms (not recommded), or deprecating the original term and adding the new fine grained terms. From a reporting / interpretation perspective the change is large enough to warrant up-versioning.</td><td>❗ Yes</td></tr></tbody></table>',9)])])}const g=t(r,[["render",o]]);export{p as __pageData,g as default};
